const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BRL=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const fmt=(n,d=2)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:d}).format(Number(n)||0);
const dateBR=d=>d?d.split('-').reverse().join('/'): '—';
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const safeTheme=()=>{try{return localStorage.getItem('metrics-theme')||'dark';}catch{return 'dark';}};
const NAV=[['dashboard','▦','Visão geral'],['ai','✧','Metrics AI'],['wallet','▤','Carteira'],['watch','☆','Desejos'],['assets','▥','Analisar'],['quotes','◈','Preços'],['income','◴','Proventos'],['calendar','▣','Calendário'],['sim','◫','Simulador'],['multi','◇','Carteira futura'],['import','⇧','Importar B3'],['docs','▧','Documentos'],['tax','▣','Relatórios'],['settings','⚙','Ajustes']];
let S={transactions:[],watchlist:[],messages:[],quotes:[],profiles:[],events:[],documents:[],imports:[],summary:{positions:[],holdingCost:0,dividends:0,realized:0,holdings:0},analytics:{positions:[],dividendsByMonth:[],dividendsByTicker:[],missingQuotes:[]},page:'dashboard',ai:{provider:'ollama',model:'qwen2.5:3b',key:'',context:false},theme:safeTheme(),busy:false,preview:null,stages:[{months:60,amount:400},{months:120,amount:500}],lastSimulation:null,multiAssets:[{ticker:'GGRC11',price:9.19,dividend:0.10,weight:50},{ticker:'VGIR11',price:9.58,dividend:0.13,weight:50}],lastMulti:null,risk:[],settings:{},taxLedger:null,marketPreview:null};
function toast(s,err=false){$('.toast')?.remove();const div=document.createElement('div');div.className='toast'+(err?' error':'');div.textContent=s;document.body.append(div);setTimeout(()=>div.remove(),5600);}
async function api(url,{method='GET',data}={}){const res=await fetch(url,{method,headers:{'X-Metrics-Local':'1',...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined});const json=await res.json();if(!res.ok)throw Error(json.error||'Falha no serviço local.');return json;}
async function update(){Object.assign(S,await api('/api/state'));S.risk=await api('/api/risk');}
const opt=(a,b)=>a===b?'selected':'';
function head(k,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subheading">${description}</p></div>${action}</div>`;}
function card(label,value,foot='',cls=''){return `<div class="card metric"><div class="metric-label">${label}</div><div class="metric-value ${cls}">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function shell(){document.documentElement.classList.toggle('light',S.theme==='light');return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="/logo.svg" class="brand-logo" alt="Metrics"><div><div class="brand-name">Metrics</div><div class="brand-small">INVESTIMENTOS</div></div></div><nav class="nav">${NAV.map(([id,ico,name])=>`<button class="item ${S.page===id?'active':''}" data-nav="${id}"><span class="nav-icon">${ico}</span><span>${name}</span></button>`).join('')}</nav><div class="side-bottom"><div class="status-box"><div class="status-line"><span class="dot"></span> Seus dados ficam neste dispositivo</div><p class="muted micro">Sem conexão à corretora · IA opcional</p></div><p class="side-footer">Metrics v0.4.0 · beta local</p></div></aside><main class="main"><header class="topbar"><span class="top-heading">Metrics / ${NAV.find(n=>n[0]===S.page)?.[2]}</span><div class="top-right"><span class="pill">◉ Local ${S.encrypted?'· criptografado':'· sem senha'}</span><button class="btn smol" id="theme">${S.theme==='dark'?'☀ Claro':'☾ Escuro'}</button></div></header><div id="content" class="page">${pages[S.page]()}</div></main></div>`;}
function positionsTable(){const rows=S.analytics.positions;if(!rows.length)return `<div class="empty">Sem posições abertas. Adicione uma compra na carteira.</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Quantidade</th><th>Preço médio</th><th>Custo</th><th>Valor estimado*</th><th>Resultado*</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="asset-pill">${esc(p.ticker)}</span></td><td>${fmt(p.quantity,6)}</td><td>${BRL(p.average)}</td><td>${BRL(p.cost)}</td><td>${p.marketValue===null?'—':BRL(p.marketValue)}</td><td class="${p.unrealized>=0?'positive':'danger-text'}">${p.unrealized===null?'—':BRL(p.unrealized)}</td></tr>`).join('')}</tbody></table></div><p class="footline">* Apenas com preços inseridos manualmente. Não são cotações ao vivo.</p>`;}
function txTable(rows,remove=true){if(!rows.length)return '<div class="empty">Nenhum lançamento neste período.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Quantidade / Valor</th><th>Origem</th>${remove?'<th></th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td>${dateBR(t.date)}</td><td><span class="asset-pill">${esc(t.ticker)}</span></td><td>${t.type==='BUY'?'Compra':t.type==='SELL'?'Venda':'Provento'}</td><td>${t.type==='DIVIDEND'?BRL(t.amount):fmt(t.quantity,6)+' × '+BRL(t.price)}</td><td>${esc(t.source||'manual')}</td>${remove?`<td><button class="btn smol danger" data-remove-tx="${esc(t.id)}">Excluir</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function chart(data,yLabel='R$'){if(!data.length)return '<div class="empty">Sem dados registrados.</div>';const max=Math.max(1,...data.map(x=>x[1]));return `<div class="bar-chart" role="img" aria-label="Gráfico de ${esc(yLabel)}"><div class="bar-track">${data.map(([label,value])=>`<div class="bar-entry" title="${esc(label)}: ${BRL(value)}"><div class="bar-fill" style="height:${Math.max(2,value/max*100)}%"></div><span>${esc(label.slice(-7))}</span></div>`).join('')}</div></div>`;}
function dashboard(){const a=S.analytics,events=(S.events||[]).filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),month=today().slice(0,7),inMonth=Object.fromEntries(a.dividendsByMonth)[month]||0;return `${head('MEU PATRIMÔNIO','Visão geral','Seus números de verdade, com contexto e sem dados inventados.')}<div class="hero"><div><h2>Investimentos sob seu controle.</h2><p>Registre operações, importe extratos, acompanhe proventos e faça perguntas à IA sobre o que você possui e deseja comprar.</p><div class="row-actions"><button class="btn primary" data-nav="ai">✧ Abrir Metrics AI</button><button class="btn" data-nav="wallet">+ Nova operação</button></div></div><div class="hero-art">◈</div></div><div class="metrics">${card('Custo das posições',BRL(S.summary.holdingCost),'Não é valor atual de mercado')}${card('Dividendos no mês',BRL(inMonth),'Apenas proventos registrados','positive')}${card('Posições abertas',fmt(S.summary.holdings,0),'Ativos em carteira')}${card('Na lista de desejos',fmt(S.watchlist.length,0),'Monitorados pela IA','blue')}</div><div class="grid-2"><section class="card"><div class="card-header"><h2>Carteira atual</h2><button class="btn link" data-nav="wallet">Gerenciar →</button></div>${positionsTable()}<div class="section-note">${a.missingQuotes?.length?'Sem preço manual em: '+esc(a.missingQuotes.join(', '))+'.':'Preços manuais podem ficar desatualizados.'} Não usamos cotação fictícia.</div></section><section class="card"><div class="card-header"><h2>Proventos registrados por mês</h2><button class="btn link" data-nav="income">Ver detalhes →</button></div>${chart((a.dividendsByMonth||[]).slice(-9))}</section></div><section class="card spaced"><div class="card-header"><h2>Próximos pagamentos cadastrados</h2><button class="btn link" data-nav="calendar">Abrir calendário →</button></div>${events.length?events.map(e=>`<div class="watch-row"><div><b>${esc(e.ticker)}</b> <span class="small muted">${dateBR(e.date)}</span><p class="small">${BRL(e.perShare)} por cota · ${e.kind==='ESTIMADO'?'estimativa pessoal':'informado como confirmado'}</p></div></div>`).join(''):'<div class="empty">Nenhum pagamento futuro cadastrado.</div>'}</section><section class="card spaced"><div class="card-header"><h2>Últimas operações</h2><button class="btn link" data-nav="wallet">Histórico completo →</button></div>${txTable([...S.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6),false)}</section>`;}
function wallet(){return `${head('CARTEIRA REAL','Meus investimentos','Lançamentos manuais, histórico auditável e preço médio ponderado.')}
<div class="metrics">${card('Custo atual',BRL(S.summary.holdingCost),'Custo histórico')}${card('Dividendos acumulados',BRL(S.summary.dividends),'Registrados manualmente','positive')}${card('Resultado em vendas',BRL(S.summary.realized),'Antes dos impostos')}${card('Ativos com saldo',S.summary.holdings,'Cotas ou ações')}</div>
<div class="grid-2"><section class="card"><h2>Posições</h2>${positionsTable()}</section><section class="card"><h2>Adicionar lançamento</h2><p class="subheading">Registre o que realmente aconteceu; a lista de desejos fica separada.</p><form id="tx-form"><div class="form-grid two"><label class="field">Operação<select class="input" name="type" id="tx-type"><option value="BUY">Compra</option><option value="SELL">Venda</option><option value="DIVIDEND">Dividendo / JCP / provento</option></select></label><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required maxlength="24"></label><label class="field">Data<input class="input" type="date" name="date" value="${today()}" required></label><label class="field" data-trade>Quantidade<input class="input" name="quantity" type="number" min="0.000001" step="any" value="1"></label><label class="field" data-trade>Preço unitário (R$)<input class="input" name="price" type="number" min="0.0001" step="any" placeholder="9.50"></label><label class="field" data-trade>Taxas (R$)<input class="input" name="fee" type="number" min="0" step="any" value="0"></label><label class="field wide hide" id="tx-dividend">Provento recebido (R$)<input class="input" name="amount" type="number" step="any" min="0.01"></label><label class="field wide">Observação<input class="input" name="notes" maxlength="300" placeholder="Opcional"></label></div><div class="form-actions"><button class="btn primary" type="submit">Salvar lançamento</button></div></form></section></div><section class="card spaced"><div class="card-header"><h2>Histórico completo</h2><span class="pill">${S.transactions.length} registros</span></div>${txTable([...S.transactions].sort((a,b)=>b.date.localeCompare(a.date)))}</section>`;}
function watch(){return `${head('PLANEJAMENTO','Lista de desejos','Seus próximos investimentos, separados das compras que já realizou.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Ativos para estudar</h2><span class="pill">${S.watchlist.length} tickers</span></div>${S.watchlist.length?S.watchlist.map(w=>`<div class="watch-row"><div><div class="watch-code">${esc(w.ticker)}</div><div class="small muted">Prioridade: ${esc(w.priority)} · Preço-alvo: ${w.target?BRL(w.target):'não definido'} · Aporte: ${w.budget?BRL(w.budget):'não definido'}</div>${w.notes?`<p class="small">${esc(w.notes)}</p>`:''}${S.quotes.find(q=>q.ticker===w.ticker)&&w.target&&S.quotes.find(q=>q.ticker===w.ticker).price<=w.target?'<p class="small positive">● Preço-alvo atingido no preço informado manualmente (não ao vivo)</p>':''}</div><div class="inline-buttons"><button class="btn smol" data-edit-watch="${esc(w.id)}">Editar</button><button class="btn smol danger" data-remove-watch="${esc(w.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Adicione ativos que deseja analisar ou comprar futuramente.</div>'}<div class="section-note">A Metrics AI consulta esta lista apenas se você autorizar o contexto. Registrar um desejo nunca altera sua carteira.</div></section><section class="card"><h2>Adicionar investimento desejado</h2><form id="watch-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" required placeholder="GGRC11"></label><label class="field">Prioridade<select class="input" name="priority"><option value="alta">Alta</option><option value="media" selected>Média</option><option value="baixa">Baixa</option></select></label><label class="field">Preço de interesse<input class="input" name="target" type="number" step="any" min="0.01"></label><label class="field">Aporte planejado<input class="input" name="budget" type="number" step="any" min="0.01"></label><label class="field wide">Motivo / objetivo<textarea class="input" name="notes" maxlength="500" rows="3" placeholder="Por que acompanhar este investimento?"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Adicionar à lista</button></div></form></section></div>`;}
function fundWarnings(p){const r=(S.risk||[]).find(x=>x.ticker===p.ticker);if(!r)return '';return `<details class="risk-details"><summary>Triagem de riscos e dados faltantes</summary>${r.warnings.map(x=>`<p class="danger-text small">⚠ ${esc(x)}</p>`).join('')}${r.positive.map(x=>`<p class="positive small">✓ ${esc(x)}</p>`).join('')}${r.missing.map(x=>`<p class="small muted">? ${esc(x)}</p>`).join('')}<p class="small muted">Não é uma nota de segurança nem recomendação.</p></details>`;}
function assets(){const list=S.profiles||[];return `${head('FICHAS FINANCEIRAS','Análise de ativos','Cadastre fundamentos verificados em relatórios. Nenhum indicador é inventado.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Ativos pesquisados</h2><span class="pill">${list.length} fichas</span></div>${list.length?list.map(p=>`<div class="watch-row"><div><b>${esc(p.ticker)} · ${esc(p.name||p.type)}</b><p class="small muted">${esc(p.type.replace('_',' '))} · ${esc(p.sector||'setor não informado')} · Fonte: ${esc(p.source)} · ${esc(p.date||'sem data')}</p><p class="small">Patrimônio: ${p.equity===null?'—':BRL(p.equity)} · Ativos: ${p.assets??'—'} · Ocupados: ${p.occupied??'—'} · DY 12m: ${p.dy12??'—'}%</p>${p.notes?`<p class="small muted">${esc(p.notes)}</p>`:''}${fundWarnings(p)}</div><button class="btn smol danger" data-remove-profile="${esc(p.ticker)}">Excluir</button></div>`).join(''):'<div class="empty">Ainda não há fichas. Você pode registrar números verificados nos relatórios que possui.</div>'}</section><section class="card"><h2>Cadastrar / atualizar ficha</h2><p class="lead">Indicadores são opcionais. Use valores de relatórios identificados por data e fonte.</p><form id="profile-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="GGRC11" required></label><label class="field">Tipo<select class="input" name="type"><option value="FII_TIJOLO">FII tijolo</option><option value="FII_PAPEL">FII papel</option><option value="FII_HIBRIDO">FII híbrido</option><option value="ACAO">Ação</option><option value="ETF">ETF</option><option value="RENDA_FIXA">Renda fixa</option><option value="OUTRO">Outro</option></select></label><label class="field">Nome<input class="input" name="name"></label><label class="field">Setor / foco<input class="input" name="sector" placeholder="Logística, shoppings, CRI..."></label><label class="field">Gestora<input class="input" name="manager"></label><label class="field">Patrimônio líquido (R$)<input class="input" name="equity" type="number" step="any" min="0"></label><label class="field">Qtd. imóveis / operações<input class="input" name="assets" type="number" step="1" min="0"></label><label class="field">Imóveis ocupados<input class="input" name="occupied" type="number" step="1" min="0"></label><label class="field">Vacância (%)<input class="input" name="vacancy" type="number" step="any" min="0" max="100"></label><label class="field">Dividendo / cota<input class="input" name="dividend" type="number" step="any" min="0"></label><label class="field">DY 12m (%)<input class="input" name="dy12" type="number" step="any" min="0"></label><label class="field">Dívidas (R$)<input class="input" name="debt" type="number" step="any" min="0"></label><label class="field">Data-base<input class="input" name="date" type="date"></label><label class="field">Fonte do dado<input class="input" name="source" placeholder="Relatório da gestora, página..."></label><label class="field wide">Observações verificadas<textarea class="input" name="notes" rows="3" maxlength="1200"></textarea></label></div><div class="form-actions"><button class="btn primary">Salvar ficha</button></div></form></section></div>`;}
function calendar(){const events=[...(S.events||[])].sort((a,b)=>a.date.localeCompare(b.date));return `${head('AGENDA','Calendário de proventos','Datas e valores cadastrados pelo usuário, separados em confirmados e estimados.')}
<div class="grid-2"><section class="card"><h2>Próximos eventos</h2>${events.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ticker</th><th>Valor / cota</th><th>Status</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td>${dateBR(e.date)}</td><td>${esc(e.ticker)}</td><td>${BRL(e.perShare)}</td><td><span class="badge ${e.kind==='ESTIMADO'?'moderate':''}">${e.kind==='ESTIMADO'?'Estimado':'Informado como confirmado'}</span></td><td><button class="btn smol danger" data-remove-event="${esc(e.id)}">×</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum evento cadastrado.</div>'}</section><section class="card"><h2>Registrar pagamento futuro</h2><form id="event-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required></label><label class="field">Data de pagamento<input class="input" name="date" type="date" required></label><label class="field">Valor por cota (R$)<input class="input" name="perShare" type="number" min="0" step="any" required></label><label class="field">Status<select class="input" name="kind"><option value="ESTIMADO">Estimado</option><option value="CONFIRMADO">Confirmado por fonte</option></select></label><label class="field wide">Fonte<input class="input" name="source" placeholder="Comunicado do fundo..." required></label><label class="field wide">Observação<input class="input" name="note"></label></div><div class="form-actions"><button class="btn primary">Salvar data</button></div></form><div class="section-note">Esta agenda não consulta eventos automaticamente. Verifique os comunicados oficiais antes de considerar pagamentos confirmados.</div></section></div>`;}
function quotes(){const rows=S.quotes||[];return `${head('VALORAÇÃO','Preços verificados','Importe o fechamento oficial COTAHIST da B3 ou registre seu preço manualmente. Não é tempo real.')}
<div class="grid-2"><section class="card"><h2>Preços informados</h2>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Preço</th><th>Data</th><th>Origem</th><th></th></tr></thead><tbody>${rows.map(q=>`<tr><td>${esc(q.ticker)}</td><td>${BRL(q.price)}</td><td>${dateBR(q.date)}</td><td><span class="small muted">${esc(q.source||"manual")}</span></td><td><button class="btn smol danger" data-remove-quote="${esc(q.ticker)}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum preço cadastrado.</div>'}</section><section class="card"><h2>Registrar preço de referência</h2><p class="lead">Use dados que você verificou. O valor de mercado estimado da carteira será calculado com o preço informado nesta tela.</p><form id="quote-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="VGIR11" required></label><label class="field">Preço observado (R$)<input class="input" name="price" type="number" step="any" min="0.001" required></label><label class="field wide">Data da observação<input class="input" name="date" type="date" value="${today()}" required></label></div><div class="form-actions"><button class="btn primary">Salvar preço</button></div></form><div class="section-note">Valor parcial com preços cadastrados: ${BRL(S.analytics.marketValue)} (${S.analytics.covered}/${S.analytics.totalPositions} posições cobertas). ${S.analytics.marketValueComplete?'Todos os ativos possuem preço de referência.':'O total não representa a carteira inteira.'}</div></section></div>
<section class="card spaced"><div class="card-header"><h2>Cotações oficiais de fechamento B3</h2><span class="pill">COTAHIST · Dados históricos</span></div><p class="lead">Use o botão de atualização para baixar um dos arquivos diários públicos da B3, ou selecione um arquivo COTAHIST ZIP/TXT exportado. Importaremos somente os tickers da carteira e da lista de desejos. O fechamento não é ajustado por eventos corporativos.</p><div class="row-actions"><button class="btn primary" id="b3-update">↻ Buscar último fechamento disponível</button><label class="btn">⇧ Importar COTAHIST ZIP/TXT<input class="hide" type="file" id="b3-price-file" accept=".zip,.txt"/></label></div><p class="small muted" id="market-feedback">Última atualização local: ${esc(S.settings?.lastB3QuoteImport?.at?.slice(0,16)||'não realizada')}. A consulta depende do servidor público da B3 estar disponível.</p><div id="market-preview"></div></section>`;}
function income(){const rows=S.transactions.filter(x=>x.type==='DIVIDEND').sort((a,b)=>b.date.localeCompare(a.date));return `${head('RENDA PASSIVA','Meus proventos','Rendimentos efetivamente lançados, agrupados por mês e por ticker.')}
<div class="metrics">${card('Total registrado',BRL(S.summary.dividends),'Proventos históricos')}${card('Últimos 12 meses',BRL(rows.filter(x=>x.date>=new Date(Date.now()-365*86400000).toISOString().slice(0,10)).reduce((s,x)=>s+x.amount,0)),'Período móvel')}${card('Ativos pagadores',Object.keys(Object.fromEntries(S.analytics.dividendsByTicker)).length,'Com histórico')}${card('Meses registrados',S.analytics.dividendsByMonth.length,'Com proventos')}</div><div class="grid-2"><section class="card"><h2>Por mês</h2>${chart(S.analytics.dividendsByMonth.slice(-18))}<div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Recebido</th></tr></thead><tbody>${S.analytics.dividendsByMonth.slice().reverse().map(([m,v])=>`<tr><td>${esc(m)}</td><td>${BRL(v)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Por ativo</h2>${S.analytics.dividendsByTicker.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Total</th></tr></thead><tbody>${S.analytics.dividendsByTicker.map(([t,v])=>`<tr><td>${esc(t)}</td><td>${BRL(v)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum dividendo registrado.</div>'}</section></div><section class="card spaced"><h2>Pagamentos individuais</h2>${txTable(rows,false)}</section>`;}
function ai(){return `${head('INTELIGÊNCIA FINANCEIRA','Metrics AI','Modelo local ou chave própria. Contexto e documentos são enviados apenas com autorização.',`<button class="btn danger" id="clear-chat">Limpar chat</button>`)}
<div class="ai-layout"><section class="card chat-box"><div class="card-header"><h2>Seu analista de dados</h2><span class="pill">${S.ai.provider==='ollama'?'Ollama local':S.ai.provider==='openai'?'API externa':'Resumo calculado'}</span></div><div class="chat-messages" id="chat-messages">${S.messages.length?S.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}"><div class="message-label">${m.role==='user'?'VOCÊ':'METRICS AI'}</div>${esc(m.content)}</div>`).join(''):'<div class="empty" style="margin:auto"><div class="emoji">✧</div><h2>O que vamos analisar?</h2><p>Analise sua carteira, documentos importados e possíveis novos investimentos.</p><p class="small">Não há busca autônoma na web nesta versão.</p></div>'}</div><form id="chat-form" class="chat-compose"><textarea class="input" id="chat-question" required rows="3" placeholder="Compare os riscos dos FIIs que tenho e dos que quero comprar."></textarea><button class="btn primary" ${S.busy?'disabled':''}>${S.busy?'Analisando…':'Enviar ↗'}</button></form></section><div class="ai-side"><section class="card"><h2>Configuração híbrida</h2><label class="field spaced-mini">Provedor<select class="input" id="ai-provider"><option value="insights" ${opt(S.ai.provider,'insights')}>Resumo local, sem modelo (grátis)</option><option value="ollama" ${opt(S.ai.provider,'ollama')}>Ollama local</option><option value="openai" ${opt(S.ai.provider,'openai')}>Chave externa (OpenAI)</option></select></label><label class="field spaced-mini">Modelo<input class="input" id="ai-model" value="${esc(S.ai.model)}" placeholder="qwen2.5:3b"></label><label class="field spaced-mini ${S.ai.provider==='openai'?'':'hide'}" id="ai-key-field">Chave de API, não armazenada<input class="input" id="ai-key" type="password" autocomplete="off" value="${esc(S.ai.key)}"></label><label class="toggle spaced-mini"><input type="checkbox" id="ai-context" ${S.ai.context?'checked':''}>Incluir carteira, desejos, preços manuais e documentos relacionados</label><div class="section-note">No modo externo, dados autorizados são enviados ao provedor. O resumo local não utiliza um modelo de linguagem. Textos recuperados dos documentos são dados não confiáveis. Sem consulta direta à B3.</div><button class="btn spaced-mini" id="test-ollama">Testar Ollama</button><p class="small muted" id="ai-status"></p></section><section class="card"><h2>Sugestões</h2>${['Quais FIIs estão na minha carteira e quais quero comprar?','Resuma o último documento importado, indicando o que ainda falta verificar.','Como a concentração por ticker mudaria se eu comprasse ativos da lista de desejos?'].map(q=>`<div class="prompt-suggestion" data-question="${esc(q)}">${esc(q)}</div>`).join('')}</section></div></div>`;}
function stageRow(stage,i){return `<div class="phase-row" data-phase="${i}"><span class="phase-count">${i+1}</span><label class="field">Meses<input class="input phase-months" type="number" min="1" max="600" value="${stage.months}" required></label><label class="field">R$ / mês<input class="input phase-amount" type="number" step="any" min="0" value="${stage.amount}" required></label><button class="btn smol danger" type="button" data-del-phase="${i}" ${S.stages.length===1?'disabled':''}>×</button></div>`;}
function simulator(){return `${head('PLANEJAMENTO','Simulador flexível','Aportes em fases, dividendos reinvestidos e evolução hipotética de longo prazo.')}
<div class="grid-2"><section class="card"><h2>Dados do ativo</h2><form id="sim-form"><div class="form-grid two"><label class="field">Preço por cota (R$)<input class="input" name="price" type="number" step="any" min="0.001" value="9.58" required></label><label class="field">Dividendo por cota (R$)<input class="input" name="dividend" type="number" step="any" min="0" value="0.13" required></label><label class="field">Reinvestimento (%)<input class="input" name="reinvestPercent" type="number" step="any" min="0" max="100" value="100" required></label><label class="field">Inflação hipotética (% ao ano)<input class="input" name="inflationAnnual" type="number" step="any" value="4"></label><label class="field">Variação do preço (% ao ano)<input class="input" name="priceGrowthAnnual" type="number" step="any" value="0"></label><label class="field">Variação do dividendo (% ao ano)<input class="input" name="dividendGrowthAnnual" type="number" step="any" value="0"></label></div><h2 class="spaced-mini">Etapas do investimento</h2><div id="phase-rows">${S.stages.map(stageRow).join('')}</div><button class="btn" id="add-phase" type="button">+ Adicionar fase</button><div class="form-actions"><button class="btn primary" type="submit">Calcular cenário</button></div></form><div class="section-note">Hipóteses ilustrativas. As projeções não preveem preços ou dividendos. Considera cotas inteiras, dividendos no início do mês e aportes no fim.</div></section><section class="card"><div class="card-header"><h2>Resultado projetado</h2><span class="pill">Motor matemático local</span></div><div id="sim-result">${S.lastSimulation?simulationResult(S.lastSimulation):'<div class="empty">Preencha os valores e clique em calcular.</div>'}</div></section></div>`;}
function simulationResult(r){const last=r.last;if(!last)return '<div class="empty">Sem períodos.</div>';const vals=r.months.filter(x=>x.month%12===0||x.month===r.months.length);return `<div class="grid-half"><div class="summary-chip"><div class="small muted">Patrimônio hipotético</div><div class="value">${BRL(last.holdingsValue)}</div></div><div class="summary-chip"><div class="small muted">Aportes</div><div class="value">${BRL(last.deposited)}</div></div><div class="summary-chip"><div class="small muted">Dividendos gerados</div><div class="value positive">${BRL(last.received)}</div></div><div class="summary-chip"><div class="small muted">Renda mensal estimada</div><div class="value blue">${BRL(last.incomeNextMonth)}</div></div></div><div class="section-title">Evolução anual do patrimônio</div>${chart(vals.map(v=>[v.month+'m',v.holdingsValue]))}<div class="section-note">${fmt(last.shares,6)} cotas · ${BRL(last.cash)} em caixa · ${BRL(last.withdrawn)} em dividendos sacados · Patrimônio corrigido pela inflação simulada: ${BRL(last.realValue)}.</div><div class="form-actions"><button id="download-sim" class="btn">↓ Exportar simulação CSV</button></div>`;}
function multiAssetRow(a,i){return `<div class="multi-asset-row"><label class="field">Ticker<input class="input asset-ticker" value="${esc(a.ticker)}" maxlength="24" required></label><label class="field">Preço R$<input class="input asset-price" type="number" min="0.0001" step="any" value="${a.price}" required></label><label class="field">Dividendo R$<input class="input asset-dividend" type="number" min="0" step="any" value="${a.dividend}" required></label><label class="field">Peso %<input class="input asset-weight" type="number" min="0" max="100" step="any" value="${a.weight}" required></label><button type="button" class="btn smol danger" data-remove-multi="${i}" aria-label="Remover ativo">×</button></div>`;}
function multiSimulator(){return `${head('CENÁRIOS DE CARTEIRA','Simular vários ativos','Compare uma carteira diversificada com compras de cotas inteiras e saldos individualizados.')}
<div class="grid-2"><section class="card"><h2>Ativos da simulação</h2><div class="section-note">Preços e dividendos são hipóteses editáveis, não cotações de mercado.</div><form id="multi-form"><div id="multi-assets">${S.multiAssets.map(multiAssetRow).join('')}</div><button class="btn" type="button" id="add-multi">+ Adicionar ativo</button><h2 class="spaced-mini">Fases de aporte (compartilhadas com simulador simples)</h2><div id="multi-phases">${S.stages.map(stageRow).join('')}</div><button class="btn" type="button" id="add-multi-stage">+ Nova fase</button><div class="form-grid two spaced-mini"><label class="field">Dividendos reinvestidos (%)<input class="input" name="reinvestPercent" type="number" value="100" min="0" max="100" step="any"></label><label class="field">Inflação anual hipotética (%)<input class="input" name="inflationAnnual" type="number" value="4" step="any"></label></div><div class="form-actions"><button type="submit" class="btn primary">Simular carteira</button></div></form></section><section class="card"><div class="card-header"><h2>Resultado conjunto</h2><span class="pill">Até 12 ativos</span></div><div id="multi-results">${S.lastMulti?multiResult(S.lastMulti):'<div class="empty">Configure os pesos dos ativos (somando 100%) e simule.</div>'}</div></section></div>`;}
function multiResult(r){const l=r.last;if(!l)return '<div class="empty">Sem resultado.</div>';const years=r.months.filter(x=>x.month%12===0||x.month===r.months.length);return `<div class="grid-half"><div class="summary-chip"><span class="muted small">Patrimônio hipotético</span><div class="value">${BRL(l.holdingsValue)}</div></div><div class="summary-chip"><span class="muted small">Total aportado</span><div class="value">${BRL(l.deposited)}</div></div><div class="summary-chip"><span class="muted small">Dividendos gerados</span><div class="value positive">${BRL(l.received)}</div></div><div class="summary-chip"><span class="muted small">Renda mensal hipotética</span><div class="value blue">${BRL(l.incomeNextMonth)}</div></div></div><h2 class="spaced-mini">Patrimônio no tempo</h2>${chart(years.map(x=>[x.month+'m',x.holdingsValue]))}<h2 class="spaced-mini">Por ativo no último mês</h2><div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Cotas</th><th>Patrimônio</th><th>Dividendo/mês</th></tr></thead><tbody>${l.holdings.map(h=>`<tr><td>${esc(h.ticker)}</td><td>${fmt(h.shares,0)}</td><td>${BRL(h.marketValue+h.cash)}</td><td>${BRL(h.incomeNextMonth)}</td></tr>`).join('')}</tbody></table></div><div class="section-note">Saldo em caixa ${BRL(l.cash)}; dividendos sacados ${BRL(l.withdrawn)}; valor corrigido pela inflação hipotética ${BRL(l.realValue)}. Projeção não prevê desempenho futuro.</div><button type="button" id="download-multi" class="btn spaced-mini">↓ Exportar CSV</button>`;}
function bindMulti(){const sync=()=>{S.multiAssets=$$('.multi-asset-row').map(r=>({ticker:$('.asset-ticker',r).value,price:Number($('.asset-price',r).value),dividend:Number($('.asset-dividend',r).value),weight:Number($('.asset-weight',r).value)}));S.stages=$$('#multi-phases .phase-row').map(r=>({months:Number($('.phase-months',r).value),amount:Number($('.phase-amount',r).value)}));};
 $('#add-multi').onclick=()=>{sync();if(S.multiAssets.length===12)return toast('Limite de 12 ativos.',true);S.multiAssets.push({ticker:'',price:10,dividend:.1,weight:0});render();};
 $$('[data-remove-multi]').forEach(b=>b.onclick=()=>{sync();if(S.multiAssets.length===1)return toast('Mantenha pelo menos um ativo.',true);S.multiAssets.splice(Number(b.dataset.removeMulti),1);render();});
 $('#add-multi-stage').onclick=()=>{sync();if(S.stages.length>=30)return toast('Limite de 30 fases.',true);S.stages.push({months:12,amount:400});render();};
 $$('#multi-phases [data-del-phase]').forEach(b=>b.onclick=()=>{sync();if(S.stages.length<2)return;S.stages.splice(Number(b.dataset.delPhase),1);render();});
 $('#multi-form').onsubmit=async e=>{e.preventDefault();sync();try{const result=await api('/api/simulate/portfolio',{method:'POST',data:{...formValue(e.currentTarget),assets:S.multiAssets,phases:S.stages}});S.lastMulti=result;$('#multi-results').innerHTML=multiResult(result);$('#download-multi').onclick=()=>download('metrics-carteira-futura.csv',csv([['mes','fase','aportes','dividendos','sacados','patrimonio','renda_mensal'],...result.months.map(x=>[x.month,x.phase,x.deposited,x.received,x.withdrawn,x.holdingsValue,x.incomeNextMonth])]),'text/csv');}catch(err){toast(err.message,true);}};
 if(S.lastMulti&&$('#download-multi'))$('#download-multi').onclick=()=>download('metrics-carteira-futura.csv',csv([['mes','patrimonio','renda_mensal'],...S.lastMulti.months.map(x=>[x.month,x.holdingsValue,x.incomeNextMonth])]),'text/csv');}
function imports(){return `${head('ARQUIVOS DA B3','Importador de carteira','Importe XLSX ou CSV; documentos PDF podem ser guardados para análise pela IA.')}
<div class="grid-2"><section class="card"><h2>Enviar arquivo</h2><p class="lead">Selecione um relatório da B3 em Excel (.xlsx), CSV ou PDF. Verificamos colunas conhecidas e apresentamos uma prévia. Não gravamos nada sem sua confirmação.</p><div class="upload"><div class="emoji">⇧</div><b>XLSX, CSV, TSV, PDF ou TXT</b><input class="input" id="upload-file" type="file" accept=".xlsx,.csv,.tsv,.pdf,.txt"/><div class="small muted">Até 5 MB. PDF: apenas documentos com texto extraível; não vira operação automaticamente.</div></div><div class="spaced-mini"><button class="btn" id="example-csv">↓ Baixar modelo CSV</button></div><div class="section-note">Os arquivos da B3 variam de layout. Linhas desconhecidas são sinalizadas, não inventadas. Para carteira antiga incompleta, registre o saldo histórico de forma conferida antes de importar vendas.</div></section><section class="card"><h2>Revisão antes de importar</h2><div id="import-result">${importPreviewHTML()}</div></section></div><section class="card spaced"><div class="card-header"><h2>Histórico de importações</h2><span class="pill">${S.imports.length} lotes</span></div>${S.imports.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Arquivo</th><th>Data</th><th>Adicionadas</th><th>Duplicadas ignoradas</th><th></th></tr></thead><tbody>${[...S.imports].reverse().map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.date.slice(0,10))}</td><td>${x.added}</td><td>${x.duplicates}</td><td><button class="btn smol danger" data-rollback="${esc(x.id)}">Desfazer lote</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum arquivo importado.</div>'}</section>`;}
function importPreviewHTML(){const p=S.preview;if(!p)return '<div class="empty">Escolha um arquivo para ver o que foi reconhecido.</div>';if(p.kind==='document')return `<div class="summary-chip"><h2>Documento: ${esc(p.title)}</h2><p class="small muted">${p.chars} caracteres de texto extraídos.</p><pre class="doc-preview">${esc(p.preview)}</pre><form id="save-upload-doc"><label class="field">Ticker relacionado (opcional)<input class="input" name="ticker" placeholder="VGIR11"></label><label class="field spaced-mini">Data-base (opcional)<input class="input" name="referenceDate" type="date"></label><div class="form-actions"><button class="btn primary">Guardar para a IA</button></div></form></div>`;return `<div class="summary-chip"><h2>${p.operations.length} operações identificadas</h2><p class="small muted">${p.unrecognizedTotal} linhas não reconhecidas. ${p.sheets.map(s=>esc(s.sheet)+' '+esc(s.status)).join(' · ')}</p></div><div class="table-wrap preview-table"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Quantidade / valor</th></tr></thead><tbody>${p.operations.slice(0,80).map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.ticker)}</td><td>${t.type}</td><td>${t.type==='DIVIDEND'?BRL(t.amount):fmt(t.quantity,4)+' × '+BRL(t.price)}</td></tr>`).join('')}</tbody></table></div>${p.unrecognizedTotal?`<div class="section-note">Linhas ignoradas (amostra): ${esc(p.unrecognized.slice(0,12).join(', '))}. Confira o arquivo original para dados não importados.</div>`:''}<label class="toggle spaced-mini"><input type="checkbox" id="keep-duplicate-rows"> Importar também operações idênticas já cadastradas (use apenas quando confirmar que são negócios diferentes)</label><div class="form-actions"><button class="btn primary" id="commit-import" ${!p.operations.length?'disabled':''}>Importar lançamentos reconhecidos</button></div>`;}
function documents(){return `${head('BASE DE CONHECIMENTO','Meus documentos','Relatórios fornecidos pelo usuário. A IA lê trechos relevantes quando autorizada.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Documentos importados</h2><span class="pill">${S.documents.length}</span></div>${S.documents.length?S.documents.map(d=>`<div class="watch-row"><div><b>${esc(d.title)}</b><p class="small muted">${esc(d.ticker||'Sem ticker')} · ${esc(d.referenceDate||'Sem data-base')} · ${fmt(d.chars,0)} caracteres</p></div><div class="inline-buttons"><button class="btn smol" data-read-doc="${esc(d.id)}">Ler</button><button class="btn smol" data-analyze-doc="${esc(d.id)}">IA</button><button class="btn smol danger" data-remove-doc="${esc(d.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum documento. Importe um PDF/TXT na seção Importar B3.</div>'}</section><section class="card"><h2>Como a IA consulta os documentos</h2><p class="lead">O texto é armazenado localmente e pesquisado quando uma pergunta menciona o ticker ou assunto. Somente os trechos selecionados entram no contexto da IA, se você autorizar.</p><div class="section-note">Documentos fornecidos pelo usuário não são automaticamente oficiais. A IA deve diferenciar informações encontradas, interpretações e hipóteses. Não existem cotações em tempo real nem pesquisa web automática.</div><button class="btn primary spaced-mini" data-nav="import">+ Importar documento</button></section></div><section class="card spaced hide" id="doc-reading"><h2 id="doc-title"></h2><pre id="doc-text" class="doc-preview"></pre></section>`;}
function tax(){const years=[...new Set(S.transactions.map(t=>t.date.slice(0,4)))].sort().reverse(),year=years[0]||today().slice(0,4);return `${head('EXPORTAÇÕES','Relatórios e IR','Arquivos auxiliares para conferência. Não são declaração pronta para a Receita Federal.')}
<div class="metrics">${card('Operações',S.transactions.length,'Compras, vendas e proventos')}${card('Proventos informados',BRL(S.summary.dividends),'Requer verificação fiscal')}${card('Vendas realizadas',BRL(S.summary.realized),'Não é imposto calculado')}${card('Anos com histórico',years.length,'Apenas dados lançados')}</div><div class="grid-2"><section class="card"><h2>Exportar relatórios</h2><label class="field spaced-mini">Ano-calendário<select class="input" id="tax-year">${years.length?years.map(y=>`<option value="${y}">${y}</option>`).join(''):`<option value="${year}">${year}</option>`}</select></label><div class="stack-buttons"><button class="btn primary" id="export-year">↓ Relatório anual CSV</button><button class="btn" id="export-transactions">↓ Histórico completo CSV</button><button class="btn" id="export-income">↓ Proventos por mês CSV</button><button class="btn" id="export-positions">↓ Posições atuais CSV</button><button class="btn" id="export-xlsx">↓ Relatório Excel XLSX</button><button class="btn" id="print-report">⎙ Imprimir ou salvar PDF</button><button class="btn" id="calculate-ledger">▤ Calcular resultados fiscais por mês</button><button class="btn" id="export-ledger">↓ Vendas por ativo CSV</button></div></section><section class="card"><h2>Atenção ao Imposto de Renda</h2><p class="lead">O Metrics organiza informações inseridas pelo usuário, mas não apura automaticamente DARF, prejuízos compensáveis, eventos corporativos ou todas as regras por categoria e exercício.</p><div class="section-note">Confira notas de corretagem, informes de rendimentos, eventos societários e legislação vigente. Os relatórios auxiliares não substituem documentos oficiais nem revisão fiscal profissional.</div></section></div><section class="card spaced"><div class="card-header"><h2>Conciliação de vendas por mês</h2><span class="pill">Base de cálculo, NÃO DARF</span></div><div id="tax-detail">${taxDetail()}</div></section>`;}
function taxDetail(){const d=S.taxLedger;if(!d)return '<div class="empty">Escolha o ano e clique em calcular resultados. Classifique os tickers em Analisar antes de usar este relatório.</div>';return `<div class="metrics">${card('Volume vendido',BRL(d.totals.sold),'Registros presentes')}${card('Resultado líquido das vendas',BRL(d.totals.result),'Antes de tributos')}${card('Proventos cadastrados',BRL(d.totals.proceeds),'Classificação fiscal pendente')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Classe</th><th>Vendas</th><th>Ganhos</th><th>Prejuízos</th><th>Líquido</th></tr></thead><tbody>${d.monthly.map(x=>`<tr><td>${esc(x.month)}</td><td>${esc(x.kind)}</td><td>${BRL(x.volume)}</td><td>${BRL(x.gain)}</td><td>${BRL(x.loss)}</td><td>${BRL(x.netResult)}</td></tr>`).join('')}</tbody></table></div><div class="section-note">${d.issues.map(x=>'⚠ '+esc(x)).join('<hr/>')}</div><p class="small muted">Referências: Receita Federal, regras de operações em bolsa e FIIs. Conferência profissional recomendada.</p>`;}
function settings(){return `${head('PREFERÊNCIAS','Configurações','Backups, privacidade, dados locais e estado das integrações.')}
<div class="settings-grid"><section class="card"><h2>Armazenamento local</h2><div class="section-note"><b>Diretório:</b> <span class="code">${esc(S.dataLocation||'')}</span><br><b>Banco:</b> SQLite local<br><b>Criptografia em repouso:</b> ${S.encrypted?'Ativa via senha de inicialização':'Desativada por padrão'}</div><div class="stack-buttons"><button class="btn primary" id="backup">↓ Backup criptografado com senha</button><label class="btn" for="restore-file">↑ Restaurar backup JSON</label><input type="file" id="restore-file" accept=".json,application/json" class="hide"></div><div class="section-note">O backup gerado nesta versão é protegido com senha. Guarde a senha em local seguro. Backups antigos em JSON continuam legíveis. Restaurar substitui todos os dados. Para proteger o banco com senha, siga o README antes de inserir dados pessoais.</div></section><section class="card"><h2>Fontes e limitações</h2><div class="watch-row"><b>IA local</b><span class="badge">Ollama opcional</span></div><div class="watch-row"><b>IA externa</b><span class="badge">Chave do usuário</span></div><div class="watch-row"><b>Fechamento B3 COTAHIST</b><span class="badge">Sob demanda e offline</span></div><div class="watch-row"><b>CSV / XLSX</b><span class="badge">Prévia e revisão</span></div><div class="watch-row"><b>PDF com texto</b><span class="badge">Leitura local</span></div><div class="section-note">O aplicativo não envia ordens, não solicita senhas bancárias e não fornece previsões de mercado garantidas.</div></section></div>`;}
const pages={dashboard,ai,wallet,watch,assets,quotes,income,calendar,sim:simulator,multi:multiSimulator,import:imports,docs:documents,tax,settings};
function download(name,contents,type='text/plain;charset=utf-8'){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadBase64(name,b64,type){const binary=atob(b64),arr=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)arr[i]=binary.charCodeAt(i);download(name,arr,type);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(';')).join('\r\n');}
function formValue(form){return Object.fromEntries(new FormData(form).entries());}
function go(page){S.page=page;render();scrollTo(0,0);}
function render(){ $('#app').innerHTML=shell();$('#theme').onclick=()=>{S.theme=S.theme==='dark'?'light':'dark';try{localStorage.setItem('metrics-theme',S.theme);}catch{}render();};$$('[data-nav]').forEach(el=>el.onclick=()=>go(el.dataset.nav));bindPage();}
function onActions(){ $$('[data-remove-tx]').forEach(el=>el.onclick=async()=>{if(!confirm('Excluir esta operação?'))return;try{await api('/api/transactions/'+el.dataset.removeTx,{method:'DELETE'});await update();render();toast('Operação excluída.');}catch(e){toast(e.message,true);}});
 $$('[data-remove-watch]').forEach(el=>el.onclick=async()=>{if(!confirm('Remover ativo desejado?'))return;try{await api('/api/watchlist/'+el.dataset.removeWatch,{method:'DELETE'});await update();render();}catch(e){toast(e.message,true);}});
 $$('[data-edit-watch]').forEach(el=>el.onclick=async()=>{const w=S.watchlist.find(w=>w.id===el.dataset.editWatch);const target=prompt(`Novo preço de interesse para ${w.ticker} (deixe vazio para nenhum):`,w.target??'');if(target===null)return;const budget=prompt('Valor que você planeja aplicar:',w.budget??'');if(budget===null)return;const notes=prompt('Motivo para acompanhar:',w.notes??'');if(notes===null)return;try{await api('/api/watchlist/'+w.id,{method:'PUT',data:{target,budget,notes}});await update();render();toast('Lista atualizada.');}catch(e){toast(e.message,true);}});
}
function bindPage(){onActions();if(S.page==='wallet'){
 $('#tx-type').onchange=()=>{const div=$('#tx-type').value==='DIVIDEND';$$('[data-trade]').forEach(x=>x.classList.toggle('hide',div));$('#tx-dividend').classList.toggle('hide',!div);};
 $('#tx-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/transactions',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Operação salva.');}catch(x){toast(x.message,true);}};
 }if(S.page==='watch'){$('#watch-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/watchlist',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Ativo desejado adicionado.');}catch(x){toast(x.message,true);}};}
 if(S.page==='assets'){ $('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/profiles',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Ficha atualizada.');}catch(x){toast(x.message,true);}};$$('[data-remove-profile]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir esta ficha?'))return;await api('/api/profiles/'+b.dataset.removeProfile,{method:'DELETE'});await update();render();});}
 if(S.page==='calendar'){ $('#event-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/events',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Evento salvo.');}catch(x){toast(x.message,true);}};$$('[data-remove-event]').forEach(b=>b.onclick=async()=>{await api('/api/events/'+b.dataset.removeEvent,{method:'DELETE'});await update();render();});}
 if(S.page==='quotes'){
  $('#b3-update').onclick=async()=>{const btn=$('#b3-update');btn.disabled=true;$('#market-feedback').textContent='Consultando a B3...';try{const result=await api('/api/market/update',{method:'POST',data:{}});await update();render();toast(`${result.updated} preços atualizados pela B3, data-base ${dateBR(result.marketDataDate)}.`);}catch(e){$('#market-feedback').textContent=e.message;toast(e.message,true);}finally{if($('#b3-update'))$('#b3-update').disabled=false;}};
  $('#b3-price-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>24*1024*1024)throw Error('Máximo de 24MB');const data=await toBase64(file);const preview=await api('/api/market/preview',{method:'POST',data:{name:file.name,data}});S.marketPreview={...preview,name:file.name,data};$('#market-preview').innerHTML=`<div class="section-note">Encontrados ${preview.quotes.length} tickers da sua carteira/lista (de ${preview.records} registros). Fonte: ${esc(preview.source)}. Preços são fechamentos sem ajustes.</div><div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Fechamento</th><th>Data</th></tr></thead><tbody>${preview.quotes.slice(0,60).map(q=>`<tr><td>${esc(q.ticker)}</td><td>${BRL(q.price)}</td><td>${dateBR(q.date)}</td></tr>`).join('')}</tbody></table></div><button class="btn primary spaced-mini" id="b3-confirm">Confirmar atualização de preços</button>`;$('#b3-confirm').onclick=async()=>{const result=await api('/api/market/import',{method:'POST',data:{name:file.name,data}});S.marketPreview=null;await update();render();toast(`${result.updated} preços B3 atualizados; ${result.older} datas anteriores preservadas.`);};}catch(err){toast(err.message,true);}};
  $('#quote-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/quotes',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Preço de referência salvo.');}catch(x){toast(x.message,true);}};$$('[data-remove-quote]').forEach(x=>x.onclick=async()=>{await api('/api/quotes/'+x.dataset.removeQuote,{method:'DELETE'});await update();render();});}
 if(S.page==='sim')bindSimulation();if(S.page==='multi')bindMulti();if(S.page==='ai')bindAI();if(S.page==='import')bindImport();if(S.page==='docs')bindDocs();if(S.page==='tax')bindReports();if(S.page==='settings')bindSettings();}
function bindSimulation(){const sync=()=>{S.stages=$$('.phase-row').map(row=>({months:Number($('.phase-months',row).value),amount:Number($('.phase-amount',row).value)}));};
 $('#add-phase').onclick=()=>{sync();if(S.stages.length>=30){toast('Máximo de 30 fases.');return;}S.stages.push({months:12,amount:500});render();};
 $$('[data-del-phase]').forEach(b=>b.onclick=()=>{sync();S.stages.splice(Number(b.dataset.delPhase),1);render();});
 $('#sim-form').onsubmit=async e=>{e.preventDefault();sync();try{const result=await api('/api/simulate',{method:'POST',data:{...formValue(e.currentTarget),phases:S.stages}});S.lastSimulation=result;$('#sim-result').innerHTML=simulationResult(result);$('#download-sim').onclick=()=>download('metrics-simulacao.csv',csv([['mes','fase','cotas','preco','dividendo','aportes','dividendos','sacados','caixa','patrimonio','patrimonio_real','renda_mensal'],...result.months.map(x=>[x.month,x.phase,x.shares,x.price,x.dividend,x.deposited,x.received,x.withdrawn,x.cash,x.holdingsValue,x.realValue,x.incomeNextMonth])]),'text/csv');}catch(x){toast(x.message,true);}};
 if(S.lastSimulation&&$('#download-sim'))$('#download-sim').onclick=()=>download('metrics-simulacao.csv',csv([['mes','cotas','patrimonio','dividendos'],...S.lastSimulation.months.map(x=>[x.month,x.shares,x.holdingsValue,x.received])]),'text/csv');}
function bindAI(){if($('#chat-messages'))$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;
 $('#ai-provider').onchange=e=>{S.ai.provider=e.target.value;S.ai.model=S.ai.provider==='ollama'?'qwen2.5:3b':S.ai.provider==='openai'?'gpt-4.1-mini':'local';render();};
 $('#ai-model').oninput=e=>S.ai.model=e.target.value;$('#ai-context').onchange=e=>S.ai.context=e.target.checked;if($('#ai-key'))$('#ai-key').oninput=e=>S.ai.key=e.target.value;
 $('#clear-chat').onclick=async()=>{if(!confirm('Apagar histórico de conversas?'))return;await api('/api/chat/clear',{method:'POST',data:{}});S.messages=[];render();};
 $('#test-ollama').onclick=async()=>{try{const x=await api('/api/ollama/models');$('#ai-status').textContent=x.available?'Modelos: '+x.models.join(', '):'Ollama não está ativo neste computador.';}catch(x){toast(x.message,true);}};
 $$('[data-question]').forEach(x=>x.onclick=()=>{$('#chat-question').value=x.dataset.question;$('#chat-question').focus();});
 $('#chat-form').onsubmit=async e=>{e.preventDefault();if(S.busy)return;const question=$('#chat-question').value.trim();if(!question)return;S.busy=true;S.messages=[...S.messages,{role:'user',content:question}];render();try{const x=await api('/api/chat',{method:'POST',data:{provider:S.ai.provider,model:S.ai.model,key:S.ai.key,context:S.ai.context,messages:S.messages}});S.messages.push({role:'assistant',content:x.answer});}catch(err){S.messages.pop();toast(err.message,true);}finally{S.busy=false;render();}};
}
async function toBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
function bindImport(){const hook=()=>{if($('#save-upload-doc'))$('#save-upload-doc').onsubmit=async e=>{e.preventDefault();try{const p=S.preview;await api('/api/documents',{method:'POST',data:{title:p.title,text:p.text,source:'Arquivo importado',...formValue(e.currentTarget)}});S.preview=null;await update();render();toast('Documento salvo para análise com a IA.');}catch(x){toast(x.message,true);}};
 if($('#commit-import'))$('#commit-import').onclick=async()=>{const p=S.preview;if(p.unrecognizedTotal&&!confirm(`${p.unrecognizedTotal} linhas não serão importadas. Confirmar somente as ${p.operations.length} reconhecidas?`))return;try{const result=await api('/api/transactions/import',{method:'POST',data:{transactions:p.operations,name:p.name,keepDuplicates:$('#keep-duplicate-rows')?.checked===true}});S.preview=null;await update();render();toast(`${result.added} lançamentos importados, ${result.duplicates} duplicatas ignoradas.`);}catch(x){toast(x.message,true);}};};
 $('#example-csv').onclick=()=>download('metrics-modelo.csv','data;ticker;tipo;quantidade;preco;taxa;valor\n2026-10-01;MXRF11;compra;10;9,30;0;\n2026-10-15;MXRF11;dividendo;;;;1,00\n','text/csv;charset=utf-8');
 $('#upload-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Máximo de 5 MB.');$('#import-result').textContent='Analisando arquivo local...';const p=await api('/api/import/preview',{method:'POST',data:{name:f.name,data:await toBase64(f)}});S.preview={...p,name:f.name};$('#import-result').innerHTML=importPreviewHTML();hook();}catch(x){S.preview=null;$('#import-result').textContent=x.message;toast(x.message,true);}};
 $$('[data-rollback]').forEach(x=>x.onclick=async()=>{if(!confirm('Desfazer todas as operações deste lote?'))return;try{await api('/api/imports/rollback',{method:'POST',data:{id:x.dataset.rollback}});await update();render();toast('Lote desfeito.');}catch(e){toast(e.message,true);}});hook();}
function bindDocs(){$$('[data-remove-doc]').forEach(x=>x.onclick=async()=>{if(!confirm('Excluir documento armazenado?'))return;await api('/api/documents/'+x.dataset.removeDoc,{method:'DELETE'});await update();render();});$$('[data-read-doc]').forEach(x=>x.onclick=async()=>{const d=await api('/api/documents/'+x.dataset.readDoc);$('#doc-reading').classList.remove('hide');$('#doc-title').textContent=d.title;$('#doc-text').textContent=d.text;$('#doc-reading').scrollIntoView({behavior:'smooth'});});$$('[data-analyze-doc]').forEach(x=>x.onclick=()=>{const d=S.documents.find(d=>d.id===x.dataset.analyzeDoc);S.ai.context=true;go('ai');$('#chat-question').value=`Analise o documento "${d.title}" sobre ${d.ticker||'investimentos'}. Resuma fatos, riscos, indicadores, limitações e cite sua data-base.`;});}
function bindReports(){
 $('#calculate-ledger').onclick=async()=>{try{S.taxLedger=await api('/api/tax/ledger?year='+encodeURIComponent($('#tax-year').value));$('#tax-detail').innerHTML=taxDetail();}catch(e){toast(e.message,true);}};
 $('#export-xlsx').onclick=async()=>{try{const y=$('#tax-year').value;const result=await api('/api/report/xlsx?year='+encodeURIComponent(y));downloadBase64(result.filename,result.base64,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Relatório XLSX gerado com avisos de conferência.');}catch(e){toast(e.message,true);}};
 $('#export-ledger').onclick=async()=>{try{const d=S.taxLedger||await api('/api/tax/ledger?year='+encodeURIComponent($('#tax-year').value));download('metrics-apuracao-auxiliar-'+d.year+'.csv',csv([['data','ticker','classe','venda_bruta','taxas','custo_atribuido','resultado','possivel_day_trade'],...d.sales.map(x=>[x.date,x.ticker,x.kind,x.gross,x.fees,x.allocatedCost,x.gain,x.possibleDayTrade?'SIM':'NÃO'])]),'text/csv');}catch(e){toast(e.message,true);}};
 const header=['data','ticker','tipo','quantidade','preco','taxa','valor','origem'];const rows=ts=>[header,...ts.map(t=>[t.date,t.ticker,t.type,t.quantity,t.price,t.fee,t.amount,t.source])];$('#export-year').onclick=()=>{const y=$('#tax-year').value;download('metrics-relatorio-'+y+'.csv',csv(rows(S.transactions.filter(t=>t.date.startsWith(y)))),'text/csv');};$('#export-transactions').onclick=()=>download('metrics-historico.csv',csv(rows(S.transactions)),'text/csv');$('#export-income').onclick=()=>download('metrics-proventos-mensais.csv',csv([['mes','valor'],...S.analytics.dividendsByMonth]),'text/csv');$('#export-positions').onclick=()=>download('metrics-posicoes.csv',csv([['ticker','quantidade','preco_medio','custo','dividendos'],...S.summary.positions.map(p=>[p.ticker,p.quantity,p.average,p.cost,p.dividends])]),'text/csv');$('#print-report').onclick=()=>{const year=$('#tax-year').value;const tx=S.transactions.filter(t=>t.date.startsWith(year));const wrap=document.createElement('section');wrap.className='print-report';wrap.innerHTML=`<h1>Metrics Investimentos · Relatório auxiliar ${esc(year)}</h1><p>Gerado em ${dateBR(today())}. Dados informados pelo usuário; não é documento fiscal oficial.</p><h2>Operações no ano</h2>${txTable(tx,false)}<h2>Posições atuais (não reconstruídas retroativamente)</h2>${positionsTable()}<p>Confira os informes oficiais, operações faltantes e regras tributárias aplicáveis.</p>`;document.body.append(wrap);window.print();setTimeout(()=>wrap.remove(),1200);};}
function bindSettings(){$('#backup').onclick=async()=>{const password=prompt('Crie uma senha forte (mínimo 12 caracteres) para criptografar seu backup:');if(password===null)return;if(password.length<12)return toast('Use no mínimo 12 caracteres.',true);try{const data=await api('/api/backup/encrypted',{method:'POST',data:{password}});download('metrics-backup-protegido-'+today()+'.json',JSON.stringify(data,null,2),'application/json');toast('Backup protegido exportado. Guarde a senha: não é recuperável.');}catch(err){toast(err.message,true);}};$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Backup grande demais.');const raw=JSON.parse(await f.text());if(!confirm('RESTAURAR irá SUBSTITUIR todos os dados atuais. Você fez backup?'))return;if(raw.kind==='metrics-encrypted-backup'){const password=prompt('Informe a senha do backup criptografado:');if(password===null)return;await api('/api/backup/restore-encrypted',{method:'POST',data:{backup:raw,password}});}else{if(!confirm('Backup antigo sem criptografia. Confirma que deseja restaurá-lo?'))return;await api('/api/restore',{method:'POST',data:raw});}await update();render();toast('Backup restaurado.');}catch(x){toast(x.message,true);}};}
update().then(render).catch(e=>{document.body.innerHTML='<main style="padding:35px;font-family:system-ui"><h1>Falha ao iniciar Metrics</h1><pre></pre></main>';$('pre').textContent=e.message;});
